-- ============================================================================
-- CAMPUS RELAY - SUPABASE SCHEMA
-- ============================================================================
--
-- WHAT THIS IS
--   The complete database schema for a Campus Relay deployment on Supabase:
--   every table, constraint, index, the append-only triggers, row-level
--   security, and the storage bucket that backs attachments.
--
-- SOURCE OF TRUTH
--   SQLAlchemy models (backend/app/models) own the shape; Alembic owns the
--   migration history. The table DDL below is GENERATED by
--   `python -m scripts.export_supabase_schema`. Treat the generated section as
--   read-only: change a model, re-run the generator, and commit the result.
--
-- HOW TO USE IT
--   Option A - Supabase dashboard: Database -> SQL Editor -> New query, paste
--              this whole file, Run.
--   Option B - psql:  psql "$DATABASE_URL" -f supabase/schema.sql
--   Option C - let Alembic do it:  cd backend && alembic upgrade head
--              (equivalent for the table DDL; it will not create the storage
--              bucket or the RLS statements, so run this file too if you want
--              those)
--
-- CONNECTION NOTE
--   The API connects as a privileged Postgres role (see DATABASE_URL). RLS is
--   enabled defensively so that a leaked anon/service key cannot read campus
--   data through PostgREST - there are deliberately NO permissive policies.
--   All access is mediated by the API, never by the browser.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Extensions
-- ---------------------------------------------------------------------------
-- Only pgcrypto is needed beyond the Postgres defaults: `gen_random_uuid()` is
-- used by Supabase tooling, and JSONB is built in.
create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- 2. Schema
-- ---------------------------------------------------------------------------
-- Everything lives in `public`, which is what PostgREST exposes and what the
-- API's search_path resolves to.

CREATE TABLE campuses (
	name VARCHAR(160) NOT NULL, 
	code VARCHAR(32) NOT NULL, 
	city VARCHAR(80), 
	state VARCHAR(80), 
	timezone VARCHAR(64) NOT NULL, 
	default_language VARCHAR(8) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);

CREATE TABLE permissions (
	key VARCHAR(64) NOT NULL, 
	category VARCHAR(40) NOT NULL, 
	description VARCHAR(240), 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (key)
);

CREATE TABLE roles (
	key VARCHAR(32) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	description VARCHAR(240), 
	is_system BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_roles_key CHECK (key IN ('STUDENT', 'TEACHER', 'PARENT', 'MANAGEMENT')), 
	UNIQUE (key)
);

CREATE TABLE batches (
	campus_id INTEGER NOT NULL, 
	name VARCHAR(40) NOT NULL, 
	start_year INTEGER NOT NULL, 
	end_year INTEGER NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_batch_campus_name UNIQUE (campus_id, name), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_batches_campus_id ON batches (campus_id);

CREATE TABLE books (
	campus_id INTEGER NOT NULL, 
	isbn VARCHAR(24) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	author VARCHAR(160), 
	category VARCHAR(60), 
	shelf VARCHAR(40), 
	copies_total INTEGER NOT NULL, 
	copies_available INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_book_campus_isbn UNIQUE (campus_id, isbn), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_books_campus_id ON books (campus_id);

CREATE INDEX ix_books_title ON books (title);

CREATE TABLE departments (
	campus_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	code VARCHAR(32) NOT NULL, 
	kind VARCHAR(32) NOT NULL, 
	head_user_id INTEGER, 
	sla_multiplier FLOAT NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_department_campus_code UNIQUE (campus_id, code), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_departments_campus_id ON departments (campus_id);

CREATE TABLE policies (
	campus_id INTEGER NOT NULL, 
	key VARCHAR(64) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	description TEXT, 
	service_key VARCHAR(48), 
	effect VARCHAR(16) NOT NULL, 
	evaluation_order INTEGER NOT NULL, 
	conditions JSONB NOT NULL, 
	message VARCHAR(300) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_policy_campus_key UNIQUE (campus_id, key), 
	CONSTRAINT ck_effect CHECK (effect IN ('ALLOW', 'DENY', 'REQUIRE')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_policies_campus_id ON policies (campus_id);

CREATE INDEX ix_policies_campus_service ON policies (campus_id, service_key);

CREATE TABLE role_permissions (
	role_id INTEGER NOT NULL, 
	permission_id INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (role_id, permission_id), 
	FOREIGN KEY(role_id) REFERENCES roles (id) ON DELETE CASCADE, 
	FOREIGN KEY(permission_id) REFERENCES permissions (id) ON DELETE CASCADE
);

CREATE TABLE sla_rules (
	campus_id INTEGER NOT NULL, 
	service_key VARCHAR(48), 
	priority VARCHAR(16) NOT NULL, 
	target_minutes INTEGER NOT NULL, 
	at_risk_ratio FLOAT NOT NULL, 
	escalate_to_role VARCHAR(32) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_sla_rule_scope UNIQUE (campus_id, service_key, priority), 
	CONSTRAINT ck_sla_rules_priority CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'CRITICAL', 'URGENT')), 
	CONSTRAINT ck_sla_rules_escalate_role CHECK (escalate_to_role IN ('STUDENT', 'TEACHER', 'PARENT', 'MANAGEMENT')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_sla_rules_campus_id ON sla_rules (campus_id);

CREATE TABLE users (
	campus_id INTEGER NOT NULL, 
	role_id INTEGER NOT NULL, 
	email VARCHAR(180) NOT NULL, 
	full_name VARCHAR(160) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	phone VARCHAR(24), 
	telegram_chat_id VARCHAR(64), 
	whatsapp_number VARCHAR(24), 
	language VARCHAR(8) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	must_change_password BOOLEAN NOT NULL, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_user_campus_email UNIQUE (campus_id, email), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(role_id) REFERENCES roles (id) ON DELETE RESTRICT
);

CREATE INDEX ix_users_campus_id ON users (campus_id);

CREATE INDEX ix_users_campus_role ON users (campus_id, role_id);

CREATE INDEX ix_users_role_id ON users (role_id);

CREATE TABLE workflows (
	campus_id INTEGER NOT NULL, 
	key VARCHAR(48) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	description TEXT, 
	initial_state VARCHAR(32) NOT NULL, 
	allowed_states JSONB NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_workflow_campus_key UNIQUE (campus_id, key), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_workflows_campus_id ON workflows (campus_id);

CREATE TABLE years (
	campus_id INTEGER NOT NULL, 
	name VARCHAR(40) NOT NULL, 
	ordinal INTEGER NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_year_campus_name UNIQUE (campus_id, name), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE
);

CREATE INDEX ix_years_campus_id ON years (campus_id);

CREATE TABLE activities (
	campus_id INTEGER NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	state VARCHAR(12) NOT NULL, 
	description TEXT, 
	venue VARCHAR(120), 
	starts_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	ends_at TIMESTAMP WITH TIME ZONE, 
	capacity INTEGER NOT NULL, 
	created_by_user_id INTEGER, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_activities_kind CHECK (kind IN ('CLUB', 'SPORT', 'CULTURAL', 'TECHNICAL', 'COMMUNITY')), 
	CONSTRAINT ck_activities_state CHECK (state IN ('DRAFT', 'OPEN', 'CLOSED', 'CANCELLED')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(created_by_user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_activities_campus_id ON activities (campus_id);

CREATE INDEX ix_activities_window ON activities (starts_at, ends_at);

CREATE TABLE branches (
	campus_id INTEGER NOT NULL, 
	department_id INTEGER, 
	name VARCHAR(120) NOT NULL, 
	code VARCHAR(24) NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_branch_campus_code UNIQUE (campus_id, code), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(department_id) REFERENCES departments (id) ON DELETE SET NULL
);

CREATE INDEX ix_branches_campus_id ON branches (campus_id);

CREATE INDEX ix_branches_department_id ON branches (department_id);

CREATE TABLE devices (
	campus_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	device_uid VARCHAR(80) NOT NULL, 
	platform VARCHAR(40) NOT NULL, 
	user_agent VARCHAR(300), 
	push_subscription JSONB, 
	last_seen_at TIMESTAMP WITH TIME ZONE, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_device_user_uid UNIQUE (user_id, device_uid), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_devices_campus_id ON devices (campus_id);

CREATE TABLE hostels (
	campus_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	code VARCHAR(24) NOT NULL, 
	gender VARCHAR(12) NOT NULL, 
	warden_user_id INTEGER, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_hostel_campus_code UNIQUE (campus_id, code), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(warden_user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_hostels_campus_id ON hostels (campus_id);

CREATE TABLE job_postings (
	campus_id INTEGER NOT NULL, 
	company VARCHAR(160) NOT NULL, 
	role VARCHAR(160) NOT NULL, 
	kind VARCHAR(12) NOT NULL, 
	state VARCHAR(12) NOT NULL, 
	description TEXT, 
	location VARCHAR(160), 
	eligibility VARCHAR(300), 
	package_lpa NUMERIC(6, 2), 
	apply_url VARCHAR(400), 
	deadline DATE, 
	created_by_user_id INTEGER, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_job_postings_kind CHECK (kind IN ('FULL_TIME', 'INTERNSHIP', 'PART_TIME')), 
	CONSTRAINT ck_job_postings_state CHECK (state IN ('DRAFT', 'OPEN', 'CLOSED')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(created_by_user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_job_postings_campus_id ON job_postings (campus_id);

CREATE INDEX ix_jobs_deadline ON job_postings (deadline);

CREATE TABLE notices (
	campus_id INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	content TEXT NOT NULL, 
	summary VARCHAR(300), 
	notice_type VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	priority VARCHAR(16) NOT NULL, 
	category VARCHAR(48) NOT NULL, 
	created_by_id INTEGER, 
	publish_at TIMESTAMP WITH TIME ZONE, 
	expires_at TIMESTAMP WITH TIME ZONE, 
	published_at TIMESTAMP WITH TIME ZONE, 
	archived_at TIMESTAMP WITH TIME ZONE, 
	is_pinned BOOLEAN NOT NULL, 
	acknowledgement_required BOOLEAN NOT NULL, 
	required_action VARCHAR(24), 
	required_action_label VARCHAR(80), 
	attachment_path VARCHAR(400), 
	attachment_name VARCHAR(240), 
	image_path VARCHAR(400), 
	share_token VARCHAR(64), 
	share_enabled BOOLEAN NOT NULL, 
	audience_summary VARCHAR(240), 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_notices_type CHECK (notice_type IN ('NORMAL', 'IMPORTANT', 'URGENT', 'EMERGENCY')), 
	CONSTRAINT ck_notices_status CHECK (status IN ('DRAFT', 'SCHEDULED', 'PUBLISHED', 'EXPIRED', 'ARCHIVED')), 
	CONSTRAINT ck_notices_priority CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'CRITICAL', 'URGENT')), 
	CONSTRAINT ck_notices_required_action CHECK (required_action IN ('READ', 'ACKNOWLEDGE', 'SUBMIT_FORM', 'VIEW_DOCUMENT', 'REGISTER', 'OPEN_CASE', 'VIEW_TIMETABLE')), 
	CONSTRAINT uq_notices_share_token UNIQUE (share_token), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_notices_campus_id ON notices (campus_id);

CREATE INDEX ix_notices_campus_status ON notices (campus_id, status, publish_at);

CREATE TABLE notification_preferences (
	campus_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	in_app BOOLEAN NOT NULL, 
	push BOOLEAN NOT NULL, 
	telegram BOOLEAN NOT NULL, 
	whatsapp BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_notification_pref_user_category UNIQUE (user_id, category), 
	CONSTRAINT ck_notification_prefs_category CHECK (category IN ('CASE_UPDATE', 'APPROVAL', 'CERTIFICATE_READY', 'LEAVE_STATUS', 'GATE_PASS', 'TIMETABLE', 'NOTICE', 'URGENT_ANNOUNCEMENT', 'SLA_ALERT', 'SYSTEM', 'MESS', 'ACADEMIC', 'HOSTEL')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_notification_preferences_campus_id ON notification_preferences (campus_id);

CREATE TABLE payslips (
	campus_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	period VARCHAR(7) NOT NULL, 
	basic INTEGER NOT NULL, 
	allowances INTEGER NOT NULL, 
	deductions INTEGER NOT NULL, 
	state VARCHAR(8) NOT NULL, 
	paid_on DATE, 
	reference VARCHAR(64), 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_payslip_user_period UNIQUE (user_id, period), 
	CONSTRAINT ck_payslips_state CHECK (state IN ('DRAFT', 'PAID')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_payslips_campus_id ON payslips (campus_id);

CREATE INDEX ix_payslips_period ON payslips (period);

CREATE INDEX ix_payslips_user_id ON payslips (user_id);

CREATE TABLE services (
	campus_id INTEGER NOT NULL, 
	workflow_id INTEGER, 
	department_id INTEGER, 
	key VARCHAR(48) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	description TEXT, 
	category VARCHAR(24) NOT NULL, 
	icon VARCHAR(32) NOT NULL, 
	default_priority VARCHAR(16) NOT NULL, 
	default_sla_minutes INTEGER NOT NULL, 
	allowed_requester_roles JSONB NOT NULL, 
	form_schema JSONB NOT NULL, 
	requires_attachment BOOLEAN NOT NULL, 
	allow_anonymous_location BOOLEAN NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	sort_order INTEGER NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_service_campus_key UNIQUE (campus_id, key), 
	CONSTRAINT ck_category CHECK (category IN ('HOSTEL', 'FACILITY', 'ACADEMIC', 'ADMINISTRATIVE', 'FINANCE', 'MESS', 'SECURITY', 'OTHER')), 
	CONSTRAINT ck_services_priority CHECK (default_priority IN ('LOW', 'NORMAL', 'HIGH', 'CRITICAL', 'URGENT')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(workflow_id) REFERENCES workflows (id) ON DELETE SET NULL, 
	FOREIGN KEY(department_id) REFERENCES departments (id) ON DELETE SET NULL
);

CREATE INDEX ix_services_campus_id ON services (campus_id);

CREATE TABLE staff (
	campus_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	department_id INTEGER, 
	designation VARCHAR(80) NOT NULL, 
	employee_code VARCHAR(32), 
	skills JSONB NOT NULL, 
	workload_capacity INTEGER NOT NULL, 
	is_available BOOLEAN NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_staff_user UNIQUE (user_id), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(department_id) REFERENCES departments (id) ON DELETE SET NULL
);

CREATE INDEX ix_staff_campus_id ON staff (campus_id);

CREATE INDEX ix_staff_department_id ON staff (department_id);

CREATE TABLE staff_leave (
	campus_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	state VARCHAR(16) NOT NULL, 
	from_date DATE NOT NULL, 
	to_date DATE NOT NULL, 
	reason VARCHAR(500) NOT NULL, 
	decided_by_user_id INTEGER, 
	decided_at TIMESTAMP WITH TIME ZONE, 
	decision_note VARCHAR(500), 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_staff_leave_kind CHECK (kind IN ('CASUAL', 'SICK', 'EARNED', 'MEDICAL', 'DUTY', 'OTHER')), 
	CONSTRAINT ck_staff_leave_state CHECK (state IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(decided_by_user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_staff_leave_campus_id ON staff_leave (campus_id);

CREATE INDEX ix_staff_leave_user ON staff_leave (user_id);

CREATE INDEX ix_staff_leave_user_id ON staff_leave (user_id);

CREATE INDEX ix_staff_leave_window ON staff_leave (from_date, to_date);

CREATE TABLE sync_operations (
	campus_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	device_id VARCHAR(80), 
	idempotency_key VARCHAR(80) NOT NULL, 
	operation VARCHAR(24) NOT NULL, 
	entity_type VARCHAR(32) NOT NULL, 
	entity_id VARCHAR(64), 
	status VARCHAR(24) NOT NULL, 
	attempts INTEGER NOT NULL, 
	source_channel VARCHAR(24) NOT NULL, 
	payload JSONB NOT NULL, 
	client_base JSONB NOT NULL, 
	response JSONB NOT NULL, 
	last_error TEXT, 
	captured_offline_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_sync_operations_idempotency UNIQUE (idempotency_key), 
	CONSTRAINT ck_sync_operations_operation CHECK (operation IN ('CASE_CREATE', 'CASE_COMMENT', 'CASE_STATUS', 'CASE_VERIFY', 'NOTICE_READ', 'NOTICE_ACTION', 'NOTIFICATION_READ', 'GATE_LOG')), 
	CONSTRAINT ck_sync_operations_status CHECK (status IN ('QUEUED', 'SYNCING', 'SYNCED', 'FAILED_RETRYING', 'CONFLICT', 'FAILED_REQUIRES_ACTION')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_sync_operations_campus_id ON sync_operations (campus_id);

CREATE INDEX ix_sync_operations_status ON sync_operations (status, updated_at);

CREATE INDEX ix_sync_operations_user_device ON sync_operations (user_id, device_id, created_at);

CREATE TABLE workflow_steps (
	workflow_id INTEGER NOT NULL, 
	order_index INTEGER NOT NULL, 
	key VARCHAR(48) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	step_type VARCHAR(24) NOT NULL, 
	responsible_role VARCHAR(32), 
	sla_minutes INTEGER, 
	requires_note BOOLEAN NOT NULL, 
	instructions TEXT, 
	transitions JSONB NOT NULL, 
	required_fields JSONB NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_workflow_step_key UNIQUE (workflow_id, key), 
	CONSTRAINT ck_step_type CHECK (step_type IN ('APPROVAL', 'ASSIGNMENT', 'ACTION', 'RESOLUTION', 'VERIFICATION', 'NOTIFICATION')), 
	CONSTRAINT ck_workflow_steps_role CHECK (responsible_role IN ('STUDENT', 'TEACHER', 'PARENT', 'MANAGEMENT')), 
	FOREIGN KEY(workflow_id) REFERENCES workflows (id) ON DELETE CASCADE
);

CREATE INDEX ix_workflow_steps_workflow_id ON workflow_steps (workflow_id);

CREATE TABLE blocks (
	campus_id INTEGER NOT NULL, 
	hostel_id INTEGER NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	code VARCHAR(16) NOT NULL, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_block_hostel_code UNIQUE (hostel_id, code), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(hostel_id) REFERENCES hostels (id) ON DELETE CASCADE
);

CREATE INDEX ix_blocks_campus_id ON blocks (campus_id);

CREATE INDEX ix_blocks_hostel_id ON blocks (hostel_id);

CREATE TABLE notice_reads (
	campus_id INTEGER NOT NULL, 
	notice_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	state VARCHAR(20) NOT NULL, 
	delivered_at TIMESTAMP WITH TIME ZONE, 
