CREATE TABLE cases (
	campus_id INTEGER NOT NULL, 
	case_number VARCHAR(24) NOT NULL, 
	requester_id INTEGER, 
	requester_role VARCHAR(32) NOT NULL, 
	requester_student_id INTEGER, 
	created_by_id INTEGER, 
	service_id INTEGER, 
	service_key VARCHAR(48) NOT NULL, 
	category VARCHAR(48) NOT NULL, 
	subcategory VARCHAR(64), 
	title VARCHAR(200) NOT NULL, 
	description TEXT NOT NULL, 
	location_id INTEGER, 
	asset_id INTEGER, 
	department_id INTEGER, 
	assigned_staff_id INTEGER, 
	priority VARCHAR(16) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	current_step_key VARCHAR(48), 
	source_channel VARCHAR(24) NOT NULL, 
	language VARCHAR(8) NOT NULL, 
	sla_minutes INTEGER, 
	due_at TIMESTAMP WITH TIME ZONE, 
	sla_state VARCHAR(16) NOT NULL, 
	first_response_at TIMESTAMP WITH TIME ZONE, 
	breached_at TIMESTAMP WITH TIME ZONE, 
	at_risk_notified_at TIMESTAMP WITH TIME ZONE, 
	escalation_level INTEGER NOT NULL, 
	required_approvals JSONB NOT NULL, 
	state_payload JSONB NOT NULL, 
	verification_state VARCHAR(20) NOT NULL, 
	resolution_note TEXT, 
	resolved_at TIMESTAMP WITH TIME ZONE, 
	closed_at TIMESTAMP WITH TIME ZONE, 
	last_activity_at TIMESTAMP WITH TIME ZONE DEFAULT 'now()' NOT NULL, 
	reopen_count INTEGER NOT NULL, 
	parent_case_id INTEGER, 
	duplicate_group_id VARCHAR(64), 
	dedupe_state VARCHAR(16) NOT NULL, 
	dedupe_score FLOAT, 
	client_ref VARCHAR(80), 
	captured_offline_at TIMESTAMP WITH TIME ZONE, 
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_case_campus_number UNIQUE (campus_id, case_number), 
	CONSTRAINT ck_status CHECK (status IN ('DRAFT', 'SUBMITTED', 'VALIDATING', 'ROUTED', 'ASSIGNED', 'IN_PROGRESS', 'WAITING_FOR_USER', 'WAITING_FOR_APPROVAL', 'ESCALATED', 'RESOLVED', 'VERIFICATION_REQUIRED', 'CLOSED', 'REOPENED', 'CANCELLED')), 
	CONSTRAINT ck_cases_priority CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'CRITICAL', 'URGENT')), 
	CONSTRAINT ck_cases_source_channel CHECK (source_channel IN ('PWA', 'WEB_DESKTOP', 'KIOSK', 'ASSISTED_DESK', 'QR', 'PHONE', 'EMAIL', 'WALK_IN', 'AGENT', 'SYSTEM')), 
	CONSTRAINT ck_cases_sla_state CHECK (sla_state IN ('NO_SLA', 'ON_TIME', 'AT_RISK', 'BREACHED', 'MET', 'MISSED')), 
	CONSTRAINT ck_cases_verification_state CHECK (verification_state IN ('NOT_REQUIRED', 'PENDING', 'VERIFIED', 'DISPUTED')), 
	CONSTRAINT ck_cases_dedupe_state CHECK (dedupe_state IN ('NONE', 'SUSPECTED', 'CONFIRMED')), 
	FOREIGN KEY(campus_id) REFERENCES campuses (id) ON DELETE CASCADE, 
	FOREIGN KEY(requester_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(requester_student_id) REFERENCES students (id) ON DELETE SET NULL, 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE SET NULL, 
	FOREIGN KEY(location_id) REFERENCES locations (id) ON DELETE SET NULL, 
	FOREIGN KEY(asset_id) REFERENCES assets (id) ON DELETE SET NULL, 
	FOREIGN KEY(department_id) REFERENCES departments (id) ON DELETE SET NULL, 
	FOREIGN KEY(assigned_staff_id) REFERENCES staff (id) ON DELETE SET NULL, 
	FOREIGN KEY(parent_case_id) REFERENCES cases (id) ON DELETE SET NULL
